effects.fragment:
in vec2 vTextureCoord;
out vec4 finalColor;
uniform sampler2D uTexture;
uniform float uIntensity;
uniform vec3 uColor;
void main(void) {
  vec4 color = texture(uTexture, vTextureCoord);
  float glow = color.a * uIntensity;
  finalColor = vec4(color.rgb + uColor * glow, color.a);
}
